/* A OnePage's unpublished blocks private to signed in strangers too (round AY, run any time, after or before part 464). WHY: the policy "Anyone reads a published onepage" (made in the dashboard for every role) lets any signed in account read every column of every published OnePage through the REST API with its own session, onepages.draft_blocks (the owner's unpublished edits) and archived_blocks (blocks they removed) included; part 464 closed this for the anon key only, and row level security cannot hide a column. No signed in session in the app reads another account's OnePage: the owner's editor, onboarding and settings read their own row (owner_id = their id), a team member's OnePage is read by the server (lib/team/onepage, the service role), visitors' pages, storelib.me and the sitemaps read with the service role, and the onboarding's name check now asks the server (app/api/onepage/address) instead of reading other pages with the browser key. WHAT IT DOES: 1. makes sure the owner can still read their own row: when no permissive SELECT or ALL policy for authenticated reads auth.uid(), onepages_owner_select is created for authenticated using owner_id = auth.uid(). 2. narrows every public read policy on onepages (a permissive SELECT policy whose USING reads published and reads neither auth. nor team_) to anon only, with a notice naming it, so a signed in account reads only its own OnePage through the API; any other policy that does not read auth. is named in a notice and left alone. 3. names in a notice any policy on another table that reads onepages without reading the owner, so the owner can check it. The anon key reads published pages exactly as before (with part 464's column grants when that part has run). It does NOT change any row, any grant, the owner's policy, the server's access, or INSERT, UPDATE and DELETE. Takes a short lock on the table. A missing table or column is skipped with a notice. Safe to run again: a second run finds the owner policy there and no public policy for authenticated, and changes nothing. To check: select policyname, roles, cmd, qual from pg_policies where tablename = 'onepages'; */
DO $do$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'part 465: public.onepages does not exist here, skipped'; RETURN; END IF; IF EXISTS (SELECT 1 FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'onepages' AND p.permissive = 'PERMISSIVE' AND p.cmd IN ('SELECT', 'ALL') AND p.roles && ARRAY['authenticated', 'public']::name[] AND coalesce(p.qual, '') ~ 'auth\.uid\(\)') THEN RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'onepages' AND column_name = 'owner_id') THEN RAISE NOTICE 'part 465: public.onepages has no owner read policy and no owner_id column, left alone'; RETURN; END IF; CREATE POLICY onepages_owner_select ON public.onepages FOR SELECT TO authenticated USING (owner_id = (SELECT auth.uid())); RAISE NOTICE 'part 465: created onepages_owner_select'; END $do$;
DO $do$ DECLARE r record; narrowed int := 0; BEGIN IF to_regclass('public.onepages') IS NULL THEN RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'onepages' AND p.permissive = 'PERMISSIVE' AND p.cmd IN ('SELECT', 'ALL') AND p.roles && ARRAY['authenticated', 'public']::name[] AND coalesce(p.qual, '') ~ 'auth\.uid\(\)') THEN RAISE WARNING 'part 465: no owner read policy on public.onepages, public read policies left as they are'; RETURN; END IF; FOR r IN SELECT p.policyname, p.roles, p.qual FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'onepages' AND p.permissive = 'PERMISSIVE' AND p.cmd = 'SELECT' AND p.roles && ARRAY['authenticated', 'public']::name[] AND coalesce(p.qual, '') !~ '(auth\.|team_)' ORDER BY p.policyname LOOP IF coalesce(r.qual, '') ~ 'published' THEN EXECUTE format('ALTER POLICY %I ON public.onepages TO anon', r.policyname); narrowed := narrowed + 1; RAISE NOTICE 'part 465: policy "%" on onepages now for anon only (was %, using %)', r.policyname, r.roles, r.qual; ELSE RAISE NOTICE 'part 465: policy "%" on onepages (% using %) does not read the owner and is not a published read, left alone', r.policyname, r.roles, coalesce(r.qual, 'nothing'); END IF; END LOOP; RAISE NOTICE 'part 465: % public read policies on onepages narrowed to anon', narrowed; END $do$;
DO $do$ DECLARE r record; BEGIN FOR r IN SELECT p.tablename, p.policyname, p.roles FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename <> 'onepages' AND p.roles && ARRAY['authenticated', 'public']::name[] AND coalesce(p.qual, '') ~ 'onepages' AND coalesce(p.qual, '') !~ 'auth\.' ORDER BY 1, 2 LOOP RAISE NOTICE 'part 465: policy "%" on % (%) reads onepages without reading the owner; a signed in account now sees only its own OnePage through it', r.policyname, r.tablename, r.roles; END LOOP; END $do$;
notify pgrst, 'reload schema';
